function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3800)}
function eventLog(title,description){state.events.unshift({title,description,time:new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})});state.events=state.events.slice(0,8);save()}
function button(label,action,ico,kind=''){return `<button class="btn ${kind}" data-action="${action}">${ico?icon(ico):''}${label}</button>`}
function pill(label,type=''){return `<span class="pill ${type}">${label}</span>`}
function navigate(next){if(!labels[next])next='knowledge';page=next;location.hash=next;render()}
function renderNav(){document.querySelector('#navigation').innerHTML=['sheets','knowledge','models','gas','test','settings'].map(key=>`<a href="#${key}" class="nav-item ${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(navIcons[key])}${labels[key][0]}${key==='knowledge'?`<span class="nav-count">${state.docs.length}</span>`:''}</a>`).join('');document.querySelector('#breadcrumb-page').textContent=labels[page][0]}
function heading(title,subtitle,buttons){return `<div class="page-heading"><div><div class="eyebrow">${labels[page][1]}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${buttons||''}</div></div>`}
function metric(label,value,unit,note,ico){return `<div class="metric"><div class="metric-top">${label}${icon(ico)}</div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-bottom">${note}</div></div>`}
function status(d){return d.status==='review'?pill('待確認','amber'):d.status==='pending'?pill('等待索引','blue'):pill('已建立索引')}
function render(){renderNav();document.querySelector('#main').innerHTML=({knowledge:knowledgePage,sheets:sheetsPage,models:modelsPage,gas:gasPage,test:testPage,settings:settingsPage}[page])();if(page==='knowledge')renderFiles();if(page==='test')renderChat()}
function knowledgePage(){const ready=state.docs.filter(d=>d.status==='ready');const needs=state.docs.filter(d=>d.status==='review').length;return heading('讓文件，成為回答的依據。','管理知識來源、OCR 辨識與自動同步。',button('測試問答','go-test','chat')+button('新增來源','add-source','plus','primary'))+`<div class="metrics">${metric('知識文件',state.docs.length,'份','Drive 示範文件與本機匯入','file')}${metric('可檢索段落',ready.reduce((s,d)=>s+d.chunks,0),'段','<span class="green">✓</span> 已完成索引的文件','layers')}${metric('OCR 待確認',needs,'份',needs?'有頁面需要你檢查':'所有文件已完成檢查','scan')}${metric('同步頻率',state.config.auto?state.config.interval:'—',state.config.auto?'分鐘':'','原型排程示意 · 未連接 Drive','refresh')}</div><div class="workspace-grid"><div><section class="panel"><div class="panel-head"><div><h2>文件來源</h2><div class="panel-subtitle">只同步指定範圍內的文件</div></div><button class="btn subtle" data-action="sync" ${syncing?'disabled':''}>${icon('refresh',syncing?'spin':'')}${syncing?'同步中…':'模擬同步'}</button></div><div class="source-row"><div class="source-icon">${icon('folder')}</div><div class="source-info"><strong>${state.config.drive?'自訂 Drive 來源（待授權）':'課程小幫手 / 知識文件'}</strong><small>${escapeHTML(state.config.drive||'Google Drive 示範資料夾 · 含本機文件')}</small></div>${pill('示範來源','gray')}<button class="dots" data-action="source-settings" aria-label="修改來源設定">${icon('settings')}</button></div><div class="file-toolbar"><div class="tabs"><button class="tab ${filter==='all'?'active':''}" data-filter="all">全部文件 <span>${state.docs.length}</span></button><button class="tab ${filter==='review'?'active':''}" data-filter="review">待確認 <span>${needs}</span></button><button class="tab ${filter==='ready'?'active':''}" data-filter="ready">已就緒</button></div><label class="search">${icon('search')}<input id="file-search" type="search" placeholder="搜尋文件…" aria-label="搜尋文件" value="${escapeHTML(query)}"></label></div><div id="file-list"></div><div class="table-footer"><span>資料保存在此瀏覽器 · 共 ${state.docs.length} 份文件</span><span>示範資料</span></div></section><section class="panel flow-panel"><div class="flow-head"><h2>每次更新，都有跡可循</h2><span>只重新處理變動的內容</span></div><div class="pipeline">${[['folder','偵測變更','檔案與權限'],['scan','擷取文字','按需 OCR'],['layers','段落索引','增量更新'],['shield','驗證切換','保留有效版本']].map((v,i)=>`${i?'<span class="pipeline-arrow">→</span>':''}<div class="pipeline-step">${icon(v[0])}<div><strong>${v[1]}</strong><small>${v[2]}</small></div></div>`).join('')}</div></section><div class="tip">${icon('info')}<span>可實際匯入 TXT／Markdown 並搜尋內容；Drive 同步與 PDF OCR 為流程示範。</span></div></div><aside class="right-stack"><section class="auto-panel"><div class="auto-title"><h2>自動保持最新</h2><button class="switch" role="switch" aria-label="自動同步設定" aria-checked="${state.config.auto}" data-action="toggle-auto"></button></div><p>文件更新後，自動重建異動段落。<br>你的 Bot 就能跟上最新內容。</p><div class="setting-row"><span>檢查頻率</span><select id="sync-interval" aria-label="同步頻率"><option value="15" ${state.config.interval==='15'?'selected':''}>每 15 分鐘</option><option value="30" ${state.config.interval==='30'?'selected':''}>每 30 分鐘</option><option value="60" ${state.config.interval==='60'?'selected':''}>每小時</option></select></div><div class="setting-row"><span>智慧 OCR 辨識</span>${pill(state.config.ocr?'已啟用':'已停用')}</div><div class="setting-row"><span>每日 OCR 上限</span><span>${state.config.limit} 頁</span></div><div class="auto-divider"></div><div class="setting-row"><span>排程服務</span><span>尚未連接</span></div><button class="btn subtle" data-action="sync-settings" style="margin-top:13px">進階同步設定 ${icon('arrow')}</button></section><section class="panel activity"><h2>最近活動</h2>${(state.events.length?state.events.slice(0,3):[{title:'示範索引已就緒',description:'5 份文件可以用於來源搜尋',time:'今天 10:42'},{title:'1 份文件等待 OCR 確認',description:'第 8 頁的表格閱讀順序待檢查',time:'今天 10:38'},{title:'已載入課程知識範例',description:'此資料僅供互動體驗',time:'今天 10:30'}]).map(e=>`<div class="activity-item"><span class="activity-dot"></span><strong>${escapeHTML(e.title)}</strong><p>${escapeHTML(e.description)}</p><time>${escapeHTML(e.time)}</time></div>`).join('')}</section></aside></div>`}
function renderFiles(){const matches=state.docs.filter(d=>(filter==='all'||d.status===filter)&&d.name.toLowerCase().includes(query.toLowerCase()));document.querySelector('#file-list').innerHTML=matches.length?`<div class="table-scroll"><table class="file-table"><thead><tr><th>文件名稱</th><th>狀態</th><th>處理方式</th><th>段落</th><th></th></tr></thead><tbody>${matches.map(d=>`<tr><td><div class="file-cell"><span class="file-icon ${d.type==='DOC'?'docs':d.type==='TXT'?'txt':''}">${d.type}</span><div><button class="file-name" data-doc="${d.id}">${escapeHTML(d.name)}</button><div class="file-meta">${d.local?'本機匯入':`${d.pages} 頁（示範）`} · ${escapeHTML(d.size)}</div></div></div></td><td>${status(d)}</td><td>${d.method}</td><td>${d.status==='review'?'—':d.chunks}</td><td><button class="dots" data-doc="${d.id}" aria-label="檢視 ${escapeHTML(d.name)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">沒有符合條件的文件。<br>試試其他關鍵字，或新增文件來源。</div>'}
function openModal(title,body,footer=''){document.querySelector('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close-modal" aria-label="關閉">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;document.querySelector('#modal').showModal()}
function closeModal(){document.querySelector('#modal').close()}
function addSource(){openModal('新增知識來源',`<p>選擇文件來源，建立你的 Bot 知識範圍。</p><label class="field"><span>Google Drive 檔案或資料夾網址</span><input id="drive-url" type="url" placeholder="https://drive.google.com/drive/folders/…" value="${escapeHTML(state.config.drive)}"><small>此原型可保存來源設定；實際讀取需串接 Google 授權。</small></label><div id="drive-error" class="modal-error"></div><div class="status-banner">想先試用？匯入本機 TXT 或 Markdown，可立即搜尋實際內容。單檔上限 1 MB。</div>${button('選擇文字文件','upload-doc','upload')}`,button('取消','close-modal')+button('保存 Drive 來源','save-drive','check','primary'))}
function validGoogleUrl(v,kind){try{const u=new URL(v);return u.protocol==='https:'&&(kind==='sheet'?u.hostname==='docs.google.com'&&/^\/spreadsheets\/d\/[a-zA-Z0-9_-]+/.test(u.pathname):['drive.google.com','docs.google.com'].includes(u.hostname)&&/^\/(drive\/folders\/|file\/d\/|document\/d\/|spreadsheets\/d\/|presentation\/d\/)/.test(u.pathname))}catch{return false}}
function saveDrive(){const value=document.querySelector('#drive-url').value.trim();if(!validGoogleUrl(value,'drive')){document.querySelector('#drive-error').textContent='請輸入有效的 Google Drive 檔案、資料夾或 Google 文件網址。';return}state.config.drive=value;save();closeModal();render();toast('已保存來源設定。Google 授權尚未連接。')}
function syncSettings(){openModal('同步與 OCR 設定',`<div class="status-banner warn">以下設定先保存在此瀏覽器。背景排程與 OCR 服務尚未連接。</div><label class="field"><span>同步頻率</span><select id="modal-frequency">${['15','30','60'].map(v=>`<option value="${v}" ${state.config.interval===v?'selected':''}>每 ${v} 分鐘</option>`).join('')}</select></label><label class="field"><span>每日 OCR 頁數上限</span><input id="ocr-limit" type="number" min="1" max="10000" value="${state.config.limit}"><small>達到上限時暫停新工作，避免超出預算。</small></label><label class="setting-item"><span>包含子資料夾</span><input id="subfolders" type="checkbox" ${state.config.subfolders?'checked':''}></label><label class="setting-item"><span>自動判斷需要 OCR 的頁面</span><input id="ocr-enabled" type="checkbox" ${state.config.ocr?'checked':''}></label><div id="settings-error" class="modal-error"></div>`,button('取消','close-modal')+button('保存設定','save-sync','check','primary'))}
async function syncDemo(){if(syncing)return;syncing=true;render();const stages=['正在檢查示範來源…','正在比較段落內容…','驗證新版索引…'];for(const stage of stages){toast(stage);await new Promise(r=>setTimeout(r,550))}let count=0;state.docs.forEach(d=>{if(d.status==='pending'){d.status='ready';d.chunks=chunkText(d.text).length;count++}});syncing=false;eventLog('模擬同步完成',count?`${count} 份本機文件已建立文字索引`:'未發現示範文件的內容變更');render();toast(count?`${count} 份本機文件已可搜尋`:'模擬完成：沒有異動。未呼叫 Google Drive。');return {mode:'demo',indexed:count}}
function chunkText(text){return text.split(/\n\s*\n/).flatMap(p=>p.trim().match(/[\s\S]{1,550}/g)||[]).filter(Boolean)}
async function importDocs(files){let added=0;for(const f of files){if(!/\.(txt|md)$/i.test(f.name)||f.size>1024*1024){toast('僅支援 1 MB 以內的 TXT／Markdown 文件。');continue}const text=await f.text();if(!text.trim()){toast(`${f.name} 沒有文字內容。`);continue}state.docs.push({id:uid(),name:f.name,type:'TXT',pages:null,status:'ready',chunks:chunkText(text).length,method:'文字擷取',time:'剛剛',size:`${Math.max(1,Math.round(f.size/1024))} KB`,text,local:true});added++}if(added){eventLog('已匯入文字文件',`${added} 份文件已建立本機文字索引`);render();toast(`已匯入 ${added} 份文件，可到對話測試搜尋。`)}document.querySelector('#document-input').value=''}
function documentDetail(id){const d=state.docs.find(d=>d.id===id);if(!d)return;openModal(escapeHTML(d.name),`<div class="actions section-space">${status(d)}${pill(d.local?'本機文字文件':'示範文件','gray')}${pill(d.method,'gray')}</div>${d.status==='review'?'<div class="status-banner warn">OCR 檢查示範：第 8 頁表格的閱讀順序需確認。以下為預先準備的文字，未執行 OCR。</div>':''}<div class="label-line"><span>${d.status==='review'?'可修正辨識文字':'文件內容預覽'}</span><span>${d.chunks} 段</span></div>${d.status==='review'?`<label class="field"><textarea id="ocr-text" style="min-height:210px" aria-label="OCR 辨識文字">${escapeHTML(d.text)}</textarea></label>`:`<div class="text-preview">${escapeHTML(d.text)}</div>`}<p class="note">${d.local?'這份內容僅儲存在目前瀏覽器，未上傳雲端。':'頁碼、文件名稱與內容均為示範資料。'}</p>`,`<button class="btn danger" data-delete="${d.id}">${icon('trash')}移除文件</button>${d.status==='review'?`<button class="btn primary" data-approve="${d.id}">${icon('check')}確認文字並建立索引</button>`:button('關閉','close-modal')}`)}
function sheetsPage(){const sample=[{name:'課程資料',headers:['課程編號','課程名稱','上課日期','費用','剩餘名額'],rows:[['C001','AI 應用入門','2026-10-05','1200','18'],['C002','提示詞設計工作坊','2026-10-12','1500','12'],['C003','GAS 自動化實作','2026-10-19','1800','8']]},{name:'Setting',headers:['設定鍵','設定值'],rows:configRows()},{name:'報名紀錄',headers:['報名編號','課程編號','學員姓名','付款狀態'],rows:[['R001','C001','示範學員 A','已付款'],['R002','C002','示範學員 B','待付款']]}];const sheets=state.sheet?[state.sheet,{name:'Setting',headers:['設定鍵','設定值'],rows:configRows()}]:sample;if(activeSheet>=sheets.length)activeSheet=0;const current=sheets[activeSheet];return heading('讓程式，讀懂你的試算表。','先確認工作表與欄位，再產生對應的 GAS。',button('匯入 CSV','upload-sheet','upload')+button('連接試算表','connect-sheet','link','primary'))+`<div class="status-banner">${state.sheet?'已讀取本機 CSV。第二個工作表是設定預覽，未寫回 Google。':'目前顯示示範試算表，可匯入自己的 CSV 實際辨識欄位。'}</div><section class="panel section-space"><div class="panel-head"><div><h2>${state.sheet?escapeHTML(state.sheet.name):'課程小幫手 · 資料中心'}</h2><div class="panel-subtitle">${sheets.length} 個工作表 · ${state.sheet?'本機 CSV':'示範資料'} · 預設第一列為欄位名稱</div></div>${pill('Google 尚未授權','gray')}</div><div class="data-tabs">${sheets.map((s,i)=>`<button class="btn small ${activeSheet===i?'selected':''}" data-sheet-tab="${i}">${icon('sheet')}${escapeHTML(s.name)}${i===1?' · 設定表':''}</button>`).join('')}</div><div class="table-scroll"><table><thead><tr>${current.headers.map(h=>`<th>${escapeHTML(h)}</th>`).join('')}</tr></thead><tbody>${current.rows.slice(0,10).map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="table-footer">${current.headers.length} 個欄位 · 預覽前 ${Math.min(current.rows.length,10)} 筆 <span>原型僅使用第一列作為標題</span></div></section><div class="two-column"><section class="panel panel-pad"><h2 class="section-space">欄位檢查</h2><div class="info-list"><div class="info-line"><span>標題列</span>第 1 列</div><div class="info-line"><span>空白或重複欄名</span>${validateHeaders(current.headers)||'未發現'}</div><div class="info-line"><span>資料操作</span>第一版範本：唯讀查詢</div></div><p class="note">CSV 不包含其他工作表。完整 Sheets 掃描需連接 Google 授權。</p></section><section class="panel panel-pad"><h2 class="section-space">第二個工作表：Setting</h2><p class="readable-note">AI 角色、觸發關鍵詞與 Drive 來源統一在設定表管理。正式版首次確認後會綁定工作表識別碼。</p><div style="margin-top:20px">${button('編輯Setting','go-settings','settings')}</div></section></div>`}
function validateHeaders(headers){if(headers.some(h=>!h.trim()))return '含空白欄名，請修正';if(new Set(headers).size!==headers.length)return '含重複欄名，請修正';return ''}
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else if(quoted||field==='')quoted=!quoted;else field+=c}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('CSV 的引號未成對，請檢查檔案。');row.push(field);if(row.some(x=>x.trim()))rows.push(row);return rows}
async function importSheet(file){if(!file)return;try{if(file.size>1024*1024)throw Error('CSV 上限為 1 MB。');const rows=parseCSV((await file.text()).replace(/^\uFEFF/,''));if(rows.length<2)throw Error('CSV 至少需要一列標題與一列資料。');const headers=rows.shift().map(h=>h.trim());const issue=validateHeaders(headers);if(issue)throw Error(issue);if(rows.some(r=>r.length!==headers.length))throw Error('資料列的欄位數量與標題不一致，請修正後再匯入。');state.sheet={name:file.name.replace(/\.csv$/i,''),headers,rows};activeSheet=0;save();render();toast(`已辨識 ${headers.length} 個欄位、${rows.length} 筆資料。`)}catch(e){toast(e.message)}document.querySelector('#sheet-input').value=''}
function connectSheet(){openModal('連接 Google Sheets',`<label class="field"><span>試算表網址</span><input id="sheet-url" type="url" placeholder="https://docs.google.com/spreadsheets/d/…" value="${escapeHTML(state.config.sheetUrl)}"></label><div id="sheet-error" class="modal-error"></div><div class="status-banner warn">Google 登入與授權尚未配置。此處可保存網址；也可先匯入 CSV 檢查欄位。</div>`,button('取消','close-modal')+button('保存試算表網址','save-sheet','check','primary'))}
function modelsPage(){return heading('選擇你的 AI 搭檔。','聊天模型與程式產生模型，依需求自由配置。',pill('尚未連接模型服務','gray'))+`<div class="provider-grid">${[['OpenAI','◎','文字生成與程式撰寫'],['Gemini','✦','Google AI 模型'],['Grok','𝕏','xAI 模型']].map(([name,mark,desc])=>`<button class="panel provider ${selectedProvider===name?'selected':''}" data-provider="${name}" style="text-align:left"><div class="provider-logo">${mark}</div><strong>${name}</strong><p>${desc}</p></button>`).join('')}</div><div class="two-column"><section class="panel panel-pad"><h2 class="section-space">${selectedProvider} 連接設定</h2><div class="status-banner warn">互動原型尚無密鑰保管後端，請勿輸入真實 API Key。</div><label class="field"><span>API Key</span><input disabled type="password" placeholder="安全後端連接完成後開放輸入"><small>正式版僅加密保存在後端，不寫入試算表。</small></label><label class="field"><span>模型名稱</span><input id="manual-model" value="${escapeHTML(selectedProvider===state.config.provider?state.config.model:'')}" placeholder="取得模型清單後選擇，或先輸入規劃名稱"><small>手動輸入只保存設定，不表示模型存在或可以使用。</small></label><div class="actions">${button('檢查連線需求','model-prerequisites','link')}${button('保存模型設定','save-model','check','primary')}</div></section><section class="panel panel-pad"><h2 class="section-space">模型驗證</h2>${[['API Key 權限','未測試'],['取得可見模型','未測試'],['實際文字生成','未測試'],['回應時間與用量','—']].map(([name,result])=>`<div class="check-row"><span>${icon('shield')}${name}</span>${pill(result,'gray')}</div>`).join('')}<p class="note">真實測試應先取得模型清單，再對選定模型發送短訊息。模型清單不等於可用性驗證。</p><div class="status-banner" style="margin-top:20px">RAG 的向量模型獨立設定。本原型的問答測試使用本機文字檢索，沒有消耗 API 額度。</div></section></div>`}
function configRows(){return [['BOT_NAME',state.config.botName],['AI_PROVIDER',state.config.provider],['AI_MODEL',state.config.model||'尚未選擇'],['AI_ROLE',state.config.role],['TRIGGER_KEYWORDS',JSON.stringify(state.config.keywords.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean))],['TRIGGER_MODE',state.config.match],['DRIVE_URLS',JSON.stringify(state.config.drive?[state.config.drive]:[])],['RAG_ENABLED','true'],['NO_ANSWER_MESSAGE',state.config.fallback],['CONFIG_VERSION','1']]}
function settingsPage(){return heading('把規則，留在熟悉的地方。','對應第二個「Setting」工作表，先在這裡編輯。',button('匯出設定 CSV','export-config','download')+button('保存設定','save-config','check','primary'))+`<div class="status-banner">目前只保存於此瀏覽器。匯出 CSV 後可貼入 Google Sheets 的第二個工作表。</div><div class="two-column"><section class="panel panel-pad"><h2 class="section-space">Bot 與角色</h2><label class="field"><span>Bot 名稱</span><input id="bot-name" maxlength="80" value="${escapeHTML(state.config.botName)}"></label><label class="field"><span>AI 模型的角色設定</span><textarea id="role-text" style="min-height:170px">${escapeHTML(state.config.role)}</textarea><small>描述回答語氣、工作範圍與資料不足時的處理方式。</small></label><label class="field"><span>找不到答案時的回覆</span><textarea id="fallback-text">${escapeHTML(state.config.fallback)}</textarea></label></section><section class="panel panel-pad"><h2 class="section-space">觸發與知識來源</h2><label class="field"><span>觸發關鍵詞</span><input id="keywords" value="${escapeHTML(state.config.keywords)}"><small>以逗號分隔，例如：課程、報名、上課。</small></label><label class="field"><span>觸發方式</span><select id="match-mode">${[['contains','包含關鍵詞'],['exact','完全符合'],['prefix','以關鍵詞開頭']].map(([v,l])=>`<option value="${v}" ${state.config.match===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Google Drive 來源</span><input id="config-drive" value="${escapeHTML(state.config.drive)}" placeholder="https://drive.google.com/drive/folders/…"><small>新來源需先授權，再建立索引。</small></label><div class="info-list"><div class="info-line"><span>模型供應商</span>${escapeHTML(state.config.provider)}</div><div class="info-line"><span>設定工作表</span>第二個分頁（待綁定）</div></div><div style="margin-top:20px">${button('OCR 與同步設定','sync-settings','settings')}</div></section></div>`}
function saveConfig(){const bot=document.querySelector('#bot-name').value.trim(),role=document.querySelector('#role-text').value.trim(),fallback=document.querySelector('#fallback-text').value.trim(),drive=document.querySelector('#config-drive').value.trim(),keywords=document.querySelector('#keywords').value.trim();if(!bot||!role||!fallback||!keywords){toast('請填寫名稱、角色、關鍵詞及查無資料回覆。');return false}if(drive&&!validGoogleUrl(drive,'drive')){toast('Google Drive 網址格式不正確。');return false}Object.assign(state.config,{botName:bot,role,fallback,drive,keywords,match:document.querySelector('#match-mode').value});save();toast('設定已保存。');return true}
function generateGas(){const headers=state.sheet?.headers||['Time','userid','message','AI_Response'];const sheetName=state.sheet?.name||'Data';const urlMatch=state.config.sheetUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);return `/**\n * Relay Studio — GAS 唯讀整合範本\n * 尚未部署；AI / RAG 服務與 LINE 驗證入口需另建。\n * 在 Apps Script「專案設定 > 指令碼屬性」設定：\n * SPREADSHEET_ID、CONFIG_SHEET_ID、RAG_ENDPOINT、RAG_TOKEN\n * API Key 不應放入試算表或本檔案。\n */\nconst DATA_SHEET_NAME = ${JSON.stringify(sheetName)};\nconst EXPECTED_HEADERS = ${JSON.stringify(headers)};\nconst SUGGESTED_SPREADSHEET_ID = ${JSON.stringify(urlMatch?.[1]||'')};\n\nfunction properties_() {\n  return PropertiesService.getScriptProperties();\n}\n\nfunction spreadsheet_() {\n  const id = properties_().getProperty('SPREADSHEET_ID')\n    || SUGGESTED_SPREADSHEET_ID;\n  if (!id) throw new Error('請先設定 SPREADSHEET_ID');\n  return SpreadsheetApp.openById(id);\n}\n\n// 第一次執行：確認第二個分頁並綁定其識別碼。\nfunction setupConfigSheet() {\n  const sheet = spreadsheet_().getSheets()[1];\n  if (!sheet || !['setting', '系統設定'].includes(sheet.getName().toLowerCase())) {\n    throw new Error('第二個分頁必須先命名為「Setting」');\n  }\n  properties_().setProperty('CONFIG_SHEET_ID', String(sheet.getSheetId()));\n  return { name: sheet.getName(), id: sheet.getSheetId() };\n}\n\nfunction loadConfig_() {\n  const id = properties_().getProperty('CONFIG_SHEET_ID');\n  if (!id) throw new Error('請先執行 setupConfigSheet');\n  const sheet = spreadsheet_().getSheets()\n    .find(s => String(s.getSheetId()) === id);\n  if (!sheet) throw new Error('找不到已綁定的Setting工作表');\n  const config = {};\n  sheet.getDataRange().getDisplayValues().slice(1).forEach(row => {\n    if (row[0]) config[row[0].trim()] = row[1];\n  });\n  return config;\n}\n\nfunction readRecords_() {\n  const sheet = spreadsheet_().getSheetByName(DATA_SHEET_NAME);\n  if (!sheet) throw new Error('資料工作表不存在');\n  const values = sheet.getDataRange().getDisplayValues();\n  const headers = values.shift().map(h => h.trim());\n  if (headers.some(h => !h) || new Set(headers).size !== headers.length) {\n    throw new Error('欄名不可空白或重複');\n  }\n  EXPECTED_HEADERS.forEach(h => {\n    if (headers.indexOf(h) < 0) throw new Error('缺少欄位：' + h);\n  });\n  return values.filter(row => row.some(Boolean)).map(row =>\n    Object.fromEntries(headers.map((h, i) => [h, row[i]])));\n}\n\nfunction queryRecords_(keyword) {\n  const q = String(keyword || '').trim().toLowerCase();\n  if (!q) return [];\n  return readRecords_().filter(row =>\n    Object.values(row).some(value => value.toLowerCase().includes(q)))\n    .slice(0, 10);\n}\n\nfunction shouldTrigger_(text, config) {\n  const keys = JSON.parse(config.TRIGGER_KEYWORDS || '[]');\n  if (!Array.isArray(keys) || !keys.every(k => typeof k === 'string')) {\n    throw new Error('TRIGGER_KEYWORDS 必須是文字陣列');\n  }\n  return keys.filter(Boolean).some(key => {\n    if (config.TRIGGER_MODE === 'exact') return text === key;\n    if (config.TRIGGER_MODE === 'prefix') return text.startsWith(key);\n    return text.includes(key);\n  });\n}\n\n// RAG_ENDPOINT 為你部署的受驗證查詢服務，不是 Drive 網址。\nfunction askKnowledge_(question, config) {\n  const props = properties_();\n  const endpoint = props.getProperty('RAG_ENDPOINT');\n  const token = props.getProperty('RAG_TOKEN');\n  if (!endpoint || !/^https:\\/\\//.test(endpoint) || !token) {\n    throw new Error('請先配置 HTTPS RAG 服務與 RAG_TOKEN');\n  }\n  const response = UrlFetchApp.fetch(endpoint, {\n    method: 'post', contentType: 'application/json',\n    headers: { Authorization: 'Bearer ' + token },\n    payload: JSON.stringify({ question, role: config.AI_ROLE }),\n    muteHttpExceptions: true\n  });\n  if (response.getResponseCode() !== 200) throw new Error('RAG 查詢失敗');\n  const body = JSON.parse(response.getContentText());\n  return body.answer || config.NO_ANSWER_MESSAGE;\n}\n\nfunction testSheetConnection() {\n  const config = loadConfig_();\n  const records = readRecords_();\n  return { ok: true, rowCount: records.length, botName: config.BOT_NAME };\n}\n\n// 本範本刻意未提供公開 doPost 入口。\n// 正式 LINE 串接需：簽章驗證入口、內部請求驗證、事件去重、使用者授權。\n// 不要把私人試算表內容直接開放給所有 LINE 好友。\n`}
function gasPage(){return heading('從資料結構，到可讀的程式。','依據目前試算表與設定產生 GAS 唯讀範本。',button('檢查範本','check-gas','shield')+button('下載 .gs','download-gas','download','primary'))+`<div class="status-banner warn">這是可匯出的 GAS 範本，尚未在 Google 執行。LINE 入口、AI 與 RAG 後端尚待實作與連接。</div><div class="workspace-grid"><section><div class="panel panel-pad"><div class="flow-head"><h2>Code.gs</h2>${pill('範本預覽','gray')}</div><div class="code-box"><div class="code-header"><span>APPS SCRIPT · JAVASCRIPT</span><button class="btn subtle" data-action="copy-gas" style="color:#bdd0a7;font-size:11px">複製程式</button></div><pre><code>${escapeHTML(generateGas())}</code></pre></div></div></section><aside class="right-stack"><section class="panel panel-pad"><h2 class="section-space">範本內容</h2>${['依欄位名稱讀取資料','綁定第二個設定工作表','Keywords判斷','RAG 服務呼叫介面','連線測試函式'].map(t=>`<div class="check-row"><span>${icon('check')}${t}</span></div>`).join('')}</section><section class="panel panel-pad"><h2>接下來怎麼做</h2>${['下載程式及匯出設定 CSV','建立 Apps Script 專案並貼上範本','設定指令碼屬性及服務憑證','執行 setupConfigSheet 與連線測試'].map((t,i)=>`<div class="guide-step"><b>${i+1}</b><span>${t}</span></div>`).join('')}<p class="note">此原型不會替你部署，也不會傳送 LINE 訊息。</p></section></aside></div>`}
function triggerMatch(text){const keys=state.config.keywords.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean);return keys.some(k=>state.config.match==='exact'?text===k:state.config.match==='prefix'?text.startsWith(k):text.includes(k))}
function retrieve(question){const q=question.toLowerCase().replace(/[\s？?。，！!、]/g,'');const tokens=new Set([...q.matchAll(/[a-z0-9]+/g)].map(x=>x[0]));const chars=q.replace(/[^\u3400-\u9fff]/g,'');for(let i=0;i<chars.length-1;i++)tokens.add(chars.slice(i,i+2));if(q.length===1)tokens.add(q);const candidates=state.docs.filter(d=>d.status==='ready').flatMap(d=>chunkText(d.text).map((text,index)=>({doc:d.id,name:d.name,text,index,score:[...tokens].reduce((s,t)=>s+(text.toLowerCase().includes(t)?Math.min(t.length,5):0),0)})));return candidates.filter(c=>c.score>=2).sort((a,b)=>b.score-a.score).slice(0,2)}
function testPage(){return heading('在送出之前，先聊聊看。','測試關鍵詞對應的顯示文字與網址。',button('清除對話','clear-chat','refresh'))+`<div class="status-banner">本機規則測試：命中關鍵詞就顯示對應文字或網址；只有開啟 RAG 才搜尋文件。不發送 LINE 訊息。</div><div class="chat-layout"><section class="panel chat-panel"><div class="panel-head" style="border-bottom:1px solid var(--line)"><div class="connection-card"><span class="project-icon">學</span><div><h2>${escapeHTML(state.config.botName)}</h2><div class="panel-subtitle">關鍵詞回覆測試</div></div></div>${pill('本機測試','gray')}</div><div id="chat-messages" class="chat-messages" aria-live="polite"></div><div class="suggestions">${state.rules.filter(r=>r.enabled).slice(0,3).map(r=>r.keyword).map(q=>`<button class="suggestion" data-question="${escapeHTML(q)}">${escapeHTML(q)}</button>`).join('')}</div><form id="chat-form" class="chat-form"><input id="question" class="text-input" placeholder="輸入問題，找找文件怎麼說…" aria-label="輸入測試問題" required maxlength="1000"><button class="btn primary" type="submit">${icon('arrow')}送出</button></form></section><aside><section class="panel panel-pad section-space"><h2 class="section-space">本次測試設定</h2><div class="info-list"><div class="info-line"><span>可搜尋文件</span>${state.docs.filter(d=>d.status==='ready').length} 份</div><div class="info-line"><span>聊天模型</span>未連接</div><div class="info-line"><span>檢索方式</span>本機文字比對</div><div class="info-line"><span>觸發規則</span>${{contains:'包含',exact:'完全符合',prefix:'前綴'}[state.config.match]}</div></div><p class="note">關鍵詞：${escapeHTML(state.config.keywords)}</p></section><section class="auto-panel"><h2 style="font-size:14px">每個答案，都能回到來源。</h2><p>點選回答下方的文件，即可檢視原文。OCR 待確認的文件不會用於檢索。</p></section></aside></div>`}
function renderChat(){document.querySelector('#chat-messages').innerHTML=chatMessages.length?chatMessages.map(m=>`<div class="chat-message ${m.role}"><div class="chat-label">${m.role==='user'?'你':escapeHTML(state.config.botName)+' · 本機規則測試'}</div><div class="bubble">${escapeHTML(m.text)}${(m.citations||[]).map(c=>`<button class="citation" data-doc="${c.doc}">${icon('file')} ${escapeHTML(c.name)} · 第 ${c.index+1} 段</button>`).join('')}</div></div>`).join(''):`<div class="chat-message"><div class="chat-label">${escapeHTML(state.config.botName)} · 本機規則測試</div><div class="bubble">${escapeHTML(state.config.welcomeMessage || "輸入你設定的關鍵詞，看看 Bot 會顯示什麼文字或網址。")}</div></div>`;const el=document.querySelector('#chat-messages');el.scrollTop=el.scrollHeight}
function ask(question){question=question.trim();if(!question||question.length>1000)return;chatMessages.push({role:'user',text:question});let response;if(!triggerMatch(question))response={role:'assistant',text:`未符合目前的觸發規則。請包含以下關鍵詞：${state.config.keywords}。\n可到「Setting」調整。`};else{const matches=retrieve(question);response={role:'assistant',text:matches.length?'找到以下相關文件片段：\n\n'+matches.map((c,i)=>`${i+1}. ${c.text}`).join('\n\n'):state.config.fallback,citations:matches}}chatMessages.push(response);if(page==='test')renderChat();return {mode:'local-keyword-retrieval',matched:response.citations?.length||0,text:response.text}}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(value){const text=String(value);const safe=/^[\s\uFEFF]*[=+@\-＝＋＠－]/u.test(text)||/^[\t\r\n]/.test(text)?"'"+text:text;return '"'+safe.replace(/"/g,'""')+'"'}
function exportConfig(){const csv=[['設定鍵','設定值'],...configRows()].map(row=>row.map(csvCell).join(',')).join('\r\n');download('Setting.csv','\uFEFF'+csv,'text/csv');toast('已匯出設定 CSV。')}
function checkGas(){const code=generateGas();let syntax;try{new Function(code);syntax=true}catch{syntax=false}const checks=[['JavaScript 語法解析',syntax],['包含欄位名稱對照',code.includes('EXPECTED_HEADERS')],['設定工作表依 ID 綁定',code.includes('CONFIG_SHEET_ID')],['已配置試算表網址',!!state.config.sheetUrl]];openModal('GAS 範本檢查',`${checks.map(([l,ok])=>`<div class="check-row"><span>${l}</span>${pill(ok?'已確認':'尚未設定',ok?'':'amber')}</div>`).join('')}<div class="status-banner warn" style="margin-top:20px">以下尚未執行：Google 權限、GAS 執行、RAG 服務、模型呼叫、LINE 訊息。語法通過不等於部署成功。</div>`,button('關閉','close-modal'))}
const actions={
'go-test':()=>navigate('test'),'go-settings':()=>navigate('settings'),'add-source':addSource,'source-settings':addSource,'close-modal':closeModal,'upload-doc':()=>{closeModal();document.querySelector('#document-input').click()},'save-drive':saveDrive,'sync':syncDemo,'toggle-auto':()=>{state.config.auto=!state.config.auto;save();render();toast('已保存排程偏好。背景排程尚未連接。')},'sync-settings':syncSettings,'save-sync':()=>{const limit=Number(document.querySelector('#ocr-limit').value);if(!Number.isInteger(limit)||limit<1||limit>10000){document.querySelector('#settings-error').textContent='OCR 上限請輸入 1 至 10000 的整數。';return}Object.assign(state.config,{interval:document.querySelector('#modal-frequency').value,limit,subfolders:document.querySelector('#subfolders').checked,ocr:document.querySelector('#ocr-enabled').checked});save();closeModal();render();toast('已保存同步與 OCR 設定。')},'upload-sheet':()=>document.querySelector('#sheet-input').click(),'connect-sheet':connectSheet,'save-sheet':()=>{const value=document.querySelector('#sheet-url').value.trim();if(!validGoogleUrl(value,'sheet')){document.querySelector('#sheet-error').textContent='請輸入有效的 Google Sheets 網址。';return}state.config.sheetUrl=value;save();closeModal();render();toast('網址已保存，尚未取得 Google 讀取權限。')},'model-prerequisites':()=>openModal('真實模型測試需要的連接',`<div class="guide-step"><b>1</b><span>配置具備使用者隔離與加密儲存的後端。</span></div><div class="guide-step"><b>2</b><span>在後端保存 ${selectedProvider} API Key。</span></div><div class="guide-step"><b>3</b><span>取得模型清單，對選定模型發送一次小量測試。</span></div><p class="note">目前沒有呼叫模型，沒有产生 API 費用。</p>`,button('了解','close-modal')),'save-model':()=>{const model=document.querySelector('#manual-model').value.trim();state.config.provider=selectedProvider;state.config.model=model;save();toast('已保存模型規劃，尚未驗證可用性。')},'save-config':saveConfig,'export-config':exportConfig,'download-gas':()=>{download('Code.gs',generateGas());toast('已下載 GAS 範本，請依註解完成服務設定。')},'copy-gas':async()=>{try{await navigator.clipboard.writeText(generateGas());toast('已複製 GAS 範本。')}catch{toast('瀏覽器未允許複製，請使用下載功能。')}},'check-gas':checkGas,'clear-chat':()=>{chatMessages=[];renderChat();toast('已清除本次對話。')}
};
document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.action&&actions[target.dataset.action]){actions[target.dataset.action]();return}if(target.dataset.filter){filter=target.dataset.filter;render();return}if(target.dataset.doc){documentDetail(target.dataset.doc);return}if(target.dataset.provider){selectedProvider=target.dataset.provider;render();return}if(target.dataset.sheetTab!==undefined){activeSheet=Number(target.dataset.sheetTab);render();return}if(target.dataset.question){ask(target.dataset.question);return}if(target.dataset.approve){const doc=state.docs.find(d=>d.id===target.dataset.approve),text=document.querySelector('#ocr-text').value.trim();if(!text){toast('辨識文字不可空白。');return}doc.text=text;doc.status='ready';doc.chunks=chunkText(text).length;eventLog('OCR 文字已人工確認',`${doc.name} 已加入本機索引`);closeModal();render();toast('示範文字已確認並建立本機索引。');return}if(target.dataset.delete){const id=target.dataset.delete;const doc=state.docs.find(d=>d.id===id);openModal('移除文件',`<p>從本機知識庫移除「${escapeHTML(doc.name)}」及其索引？Google Drive 的原始檔案不會受到影響。</p>`,button('取消','close-modal')+`<button class="btn danger" data-confirm-delete="${id}">移除文件</button>`);return}if(target.dataset.confirmDelete){state.docs=state.docs.filter(d=>d.id!==target.dataset.confirmDelete);save();closeModal();render();toast('文件與本機索引已移除。')}});
document.addEventListener('input',e=>{if(e.target.id==='file-search'){query=e.target.value;renderFiles()}});
document.addEventListener('change',e=>{if(e.target.id==='sync-interval'){state.config.interval=e.target.value;save();render()}if(e.target.id==='document-input')importDocs([...e.target.files]);if(e.target.id==='sheet-input')importSheet(e.target.files[0])});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();ask(document.querySelector('#question').value);document.querySelector('#question').value=''}});
window.addEventListener('hashchange',()=>{const key=location.hash.slice(1);if(labels[key]&&page!==key){page=key;render()}});
document.querySelector('#help-button').onclick=()=>openModal('可以怎麼試用？',`<div class="guide-step"><b>1</b><span>在知識庫開啟待確認的 PDF，修正示範 OCR 文字。</span></div><div class="guide-step"><b>2</b><span>匯入 TXT／Markdown，或在試算表頁匯入 CSV。</span></div><div class="guide-step"><b>3</b><span>修改角色與關鍵詞，再到對話測試搜尋來源。</span></div><div class="guide-step"><b>4</b><span>下載 GAS 範本與設定 CSV，檢視程式結構。</span></div><p class="note">本原型的 Google、LINE、AI API、向量化與 OCR 雲端服務均尚未接通。請先使用非敏感測試資料。</p>`,button('開始試用','close-modal','arrow','primary'));
document.querySelector('#about-button').onclick=()=>document.querySelector('#help-button').click();
document.querySelector('#project-button').onclick=()=>toast('目前是「課程小幫手」示範專案。');
document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
page=labels[location.hash.slice(1)]?location.hash.slice(1):'sheets';
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_knowledge_state',title:'讀取本機知識庫狀態',description:'取得目前互動原型的文件名稱、索引狀態及模擬服務狀態。不讀取外部 Drive。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).length)throw Error('不接受參數');return {mode:'local-prototype',docs:state.docs.map(({id,name,status,chunks})=>({id,name,status,chunks})),externalServicesConnected:false}}},{name:'test_local_knowledge_query',title:'測試本機關鍵詞回覆',description:'在對話測試頁比對文字／網址規則；只在開啟 RAG 時回退到本機文件搜尋。不呼叫 AI 或 LINE。',inputSchema:{type:'object',properties:{question:{type:'string',minLength:1,maxLength:1000}},required:['question'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.question!=='string'||!input.question.trim()||input.question.length>1000||Object.keys(input).some(k=>k!=='question'))throw Error('請提供 1 至 1000 字的 question');navigate('test');return ask(input.question)}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
